datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

generator client {
  provider = "prisma-client-js"
}

model Users {
  id String @id @default(uuid()) // Unique identifier for the user
  email String @unique // User's email address, used for login
  passwordHash String // Hashed password for security
  firstName String // User's first name
  lastName String // User's last name
  role String @default("'attendee'") // User role (attendee, organizer, admin, staff)
  createdAt DateTime // Timestamp of user creation
  updatedAt DateTime // Timestamp of last update
}

model Events {
  id String @id @default(uuid()) // Unique identifier for the event
  organizerId String // Foreign key to the Users table (organizer)
  title String // Title of the event
  description String // Detailed description of the event
  startDate DateTime // Start date and time of the event
  endDate DateTime // End date and time of the event
  venueId String // Foreign key to the EventVenues table
  status String @default("'draft'") // Current status of the event (draft, pending_approval, published, cancelled, completed)
  imageUrl String? // URL to the event's main image
  category String? // Category of the event (e.g., Music, Sport, Workshop)
  createdAt DateTime // Timestamp of event creation
  updatedAt DateTime // Timestamp of last update

  // Relations:
  // [many-to-one] -> Users (via organizerId) [references]
  // [many-to-one] -> EventVenues (via venueId) [references]
}

model EventVenues {
  id String @id @default(uuid()) // Unique identifier for the venue
  name String // Name of the venue
  address String // Full address of the venue
  city String // City where the venue is located
  country String // Country where the venue is located
  latitude Float? // Latitude coordinate of the venue
  longitude Float? // Longitude coordinate of the venue
}

model TicketTypes {
  id String @id @default(uuid()) // Unique identifier for the ticket type
  eventId String // Foreign key to the Events table
  name String // Name of the ticket type (e.g., 'General Admission')
  price Float // Price of a single ticket of this type
  quantityAvailable Int // Total number of tickets of this type available for sale
  quantitySold Int @default(0) // Number of tickets of this type already sold
  saleStartsAt DateTime? // Date and time when sales for this ticket type begin
  saleEndsAt DateTime? // Date and time when sales for this ticket type end

  // Relations:
  // [many-to-one] -> Events (via eventId) [references]
}

model Orders {
  id String @id @default(uuid()) // Unique identifier for the order
  userId String // Foreign key to the Users table (attendee)
  eventId String // Foreign key to the Events table
  totalAmount Float // Total amount paid for the order
  currency String @default("'USD'") // Currency of the transaction
  status String @default("'pending'") // Status of the order (pending, completed, failed, refunded)
  paymentIntentId String? @unique // ID from the payment gateway for this transaction
  createdAt DateTime // Timestamp of order creation
  updatedAt DateTime // Timestamp of last update

  // Relations:
  // [many-to-one] -> Users (via userId) [references]
  // [many-to-one] -> Events (via eventId) [references]
}

model Tickets {
  id String @id @default(uuid()) // Unique identifier for the individual ticket
  orderId String // Foreign key to the Orders table
  ticketTypeId String // Foreign key to the TicketTypes table
  uniqueCode String @unique // Unique QR/barcode string for ticket validation
  status String @default("'purchased'") // Status of the ticket (purchased, scanned, transferred, refunded, cancelled)
  scannedAt DateTime? // Timestamp when the ticket was scanned for entry
  transferredToUserId String? // Foreign key to the Users table if ticket was transferred
  createdAt DateTime // Timestamp of ticket creation (purchase)
  updatedAt DateTime // Timestamp of last update

  // Relations:
  // [many-to-one] -> Orders (via orderId) [references]
  // [many-to-one] -> TicketTypes (via ticketTypeId) [references]
  // [many-to-one] -> Users (via transferredToUserId) [references]
}

model Notifications {
  id String @id @default(uuid()) // Unique identifier for the notification
  userId String? // Foreign key to Users (if targeted notification)
  eventId String? // Foreign key to Events (if event-specific)
  title String // Title of the notification
  message String // Content of the notification
  type String @default("'system'") // Type of notification (system, event_update, marketing)
  read Boolean @default(false) // Whether the user has read the notification
  sentAt DateTime // Timestamp when the notification was sent

  // Relations:
  // [many-to-one] -> Users (via userId) [references]
  // [many-to-one] -> Events (via eventId) [references]
}

