-- Database Type: PostgreSQL
-- Generated locally by ArchitectAI

CREATE TABLE IF NOT EXISTS "users" (
  "id" VARCHAR(255) PRIMARY KEY,
  "email" VARCHAR(255) NOT NULL UNIQUE,
  "passwordHash" VARCHAR(255) NOT NULL,
  "firstName" VARCHAR(255) NOT NULL,
  "lastName" VARCHAR(255) NOT NULL,
  "role" VARCHAR(255) NOT NULL DEFAULT ''attendee'',
  "createdAt" TIMESTAMP NOT NULL DEFAULT 'CURRENT_TIMESTAMP',
  "updatedAt" TIMESTAMP NOT NULL DEFAULT 'CURRENT_TIMESTAMP'
);

CREATE UNIQUE INDEX IF NOT EXISTS "idx_users_email" ON "users" ("email");
CREATE INDEX IF NOT EXISTS "idx_users_role" ON "users" ("role");

CREATE TABLE IF NOT EXISTS "events" (
  "id" VARCHAR(255) PRIMARY KEY,
  "organizerId" VARCHAR(255) NOT NULL,
  "title" VARCHAR(255) NOT NULL,
  "description" VARCHAR(255) NOT NULL,
  "startDate" TIMESTAMP NOT NULL,
  "endDate" TIMESTAMP NOT NULL,
  "venueId" VARCHAR(255) NOT NULL,
  "status" VARCHAR(255) NOT NULL DEFAULT ''draft'',
  "imageUrl" VARCHAR(255),
  "category" VARCHAR(255),
  "createdAt" TIMESTAMP NOT NULL DEFAULT 'CURRENT_TIMESTAMP',
  "updatedAt" TIMESTAMP NOT NULL DEFAULT 'CURRENT_TIMESTAMP'
);

CREATE INDEX IF NOT EXISTS "idx_events_organizerId" ON "events" ("organizerId");
CREATE INDEX IF NOT EXISTS "idx_events_startDate" ON "events" ("startDate");
CREATE INDEX IF NOT EXISTS "idx_events_status" ON "events" ("status");
CREATE INDEX IF NOT EXISTS "idx_events_category_startDate" ON "events" ("category", "startDate");

CREATE TABLE IF NOT EXISTS "eventvenues" (
  "id" VARCHAR(255) PRIMARY KEY,
  "name" VARCHAR(255) NOT NULL,
  "address" VARCHAR(255) NOT NULL,
  "city" VARCHAR(255) NOT NULL,
  "country" VARCHAR(255) NOT NULL,
  "latitude" NUMERIC,
  "longitude" NUMERIC
);

CREATE INDEX IF NOT EXISTS "idx_eventvenues_city" ON "eventvenues" ("city");

CREATE TABLE IF NOT EXISTS "tickettypes" (
  "id" VARCHAR(255) PRIMARY KEY,
  "eventId" VARCHAR(255) NOT NULL,
  "name" VARCHAR(255) NOT NULL,
  "price" NUMERIC NOT NULL,
  "quantityAvailable" INTEGER NOT NULL,
  "quantitySold" INTEGER NOT NULL DEFAULT 0,
  "saleStartsAt" TIMESTAMP,
  "saleEndsAt" TIMESTAMP
);

CREATE INDEX IF NOT EXISTS "idx_tickettypes_eventId" ON "tickettypes" ("eventId");

CREATE TABLE IF NOT EXISTS "orders" (
  "id" VARCHAR(255) PRIMARY KEY,
  "userId" VARCHAR(255) NOT NULL,
  "eventId" VARCHAR(255) NOT NULL,
  "totalAmount" NUMERIC NOT NULL,
  "currency" VARCHAR(255) NOT NULL DEFAULT ''USD'',
  "status" VARCHAR(255) NOT NULL DEFAULT ''pending'',
  "paymentIntentId" VARCHAR(255) UNIQUE,
  "createdAt" TIMESTAMP NOT NULL DEFAULT 'CURRENT_TIMESTAMP',
  "updatedAt" TIMESTAMP NOT NULL DEFAULT 'CURRENT_TIMESTAMP'
);

CREATE INDEX IF NOT EXISTS "idx_orders_userId" ON "orders" ("userId");
CREATE INDEX IF NOT EXISTS "idx_orders_eventId" ON "orders" ("eventId");
CREATE UNIQUE INDEX IF NOT EXISTS "idx_orders_paymentIntentId" ON "orders" ("paymentIntentId");

CREATE TABLE IF NOT EXISTS "tickets" (
  "id" VARCHAR(255) PRIMARY KEY,
  "orderId" VARCHAR(255) NOT NULL,
  "ticketTypeId" VARCHAR(255) NOT NULL,
  "uniqueCode" VARCHAR(255) NOT NULL UNIQUE,
  "status" VARCHAR(255) NOT NULL DEFAULT ''purchased'',
  "scannedAt" TIMESTAMP,
  "transferredToUserId" VARCHAR(255),
  "createdAt" TIMESTAMP NOT NULL DEFAULT 'CURRENT_TIMESTAMP',
  "updatedAt" TIMESTAMP NOT NULL DEFAULT 'CURRENT_TIMESTAMP'
);

CREATE INDEX IF NOT EXISTS "idx_tickets_orderId" ON "tickets" ("orderId");
CREATE INDEX IF NOT EXISTS "idx_tickets_ticketTypeId" ON "tickets" ("ticketTypeId");
CREATE UNIQUE INDEX IF NOT EXISTS "idx_tickets_uniqueCode" ON "tickets" ("uniqueCode");
CREATE INDEX IF NOT EXISTS "idx_tickets_transferredToUserId" ON "tickets" ("transferredToUserId");

CREATE TABLE IF NOT EXISTS "notifications" (
  "id" VARCHAR(255) PRIMARY KEY,
  "userId" VARCHAR(255),
  "eventId" VARCHAR(255),
  "title" VARCHAR(255) NOT NULL,
  "message" VARCHAR(255) NOT NULL,
  "type" VARCHAR(255) NOT NULL DEFAULT ''system'',
  "read" BOOLEAN NOT NULL DEFAULT false,
  "sentAt" TIMESTAMP NOT NULL DEFAULT 'CURRENT_TIMESTAMP'
);

CREATE INDEX IF NOT EXISTS "idx_notifications_userId_read" ON "notifications" ("userId", "read");
CREATE INDEX IF NOT EXISTS "idx_notifications_eventId" ON "notifications" ("eventId");

