/**
 * Mongoose Models
 * Generated locally by ArchitectAI
 */

const mongoose = require('mongoose');

// --- Users Schema ---
const UsersSchema = new mongoose.Schema({
  email: {
    type: String,
    required: true,
    unique: true,
    description: "User's email address, used for login"
  },
  passwordHash: {
    type: String,
    required: true,
    description: "Hashed password for security"
  },
  firstName: {
    type: String,
    required: true,
    description: "User's first name"
  },
  lastName: {
    type: String,
    required: true,
    description: "User's last name"
  },
  role: {
    type: String,
    required: true,
    default: "'attendee'",
    description: "User role (attendee, organizer, admin, staff)"
  },
  createdAt: {
    type: Date,
    required: true,
    default: CURRENT_TIMESTAMP,
    description: "Timestamp of user creation"
  },
  updatedAt: {
    type: Date,
    required: true,
    default: CURRENT_TIMESTAMP,
    description: "Timestamp of last update"
  },
}, {
  timestamps: true
});

UsersSchema.index({"email":1}, {"unique":true});
UsersSchema.index({"role":1}, {"unique":false});
const Users = mongoose.model('Users', UsersSchema);

// --- Events Schema ---
const EventsSchema = new mongoose.Schema({
  organizerId: {
    type: String,
    required: true,
    description: "Foreign key to the Users table (organizer)"
  },
  title: {
    type: String,
    required: true,
    description: "Title of the event"
  },
  description: {
    type: String,
    required: true,
    description: "Detailed description of the event"
  },
  startDate: {
    type: Date,
    required: true,
    description: "Start date and time of the event"
  },
  endDate: {
    type: Date,
    required: true,
    description: "End date and time of the event"
  },
  venueId: {
    type: String,
    required: true,
    description: "Foreign key to the EventVenues table"
  },
  status: {
    type: String,
    required: true,
    default: "'draft'",
    description: "Current status of the event (draft, pending_approval, published, cancelled, completed)"
  },
  imageUrl: {
    type: String,
    required: false,
    description: "URL to the event's main image"
  },
  category: {
    type: String,
    required: false,
    description: "Category of the event (e.g., Music, Sport, Workshop)"
  },
  createdAt: {
    type: Date,
    required: true,
    default: CURRENT_TIMESTAMP,
    description: "Timestamp of event creation"
  },
  updatedAt: {
    type: Date,
    required: true,
    default: CURRENT_TIMESTAMP,
    description: "Timestamp of last update"
  },
}, {
  timestamps: true
});

EventsSchema.index({"organizerId":1}, {"unique":false});
EventsSchema.index({"startDate":1}, {"unique":false});
EventsSchema.index({"status":1}, {"unique":false});
EventsSchema.index({"category":1,"startDate":1}, {"unique":false});
const Events = mongoose.model('Events', EventsSchema);

// --- EventVenues Schema ---
const EventVenuesSchema = new mongoose.Schema({
  name: {
    type: String,
    required: true,
    description: "Name of the venue"
  },
  address: {
    type: String,
    required: true,
    description: "Full address of the venue"
  },
  city: {
    type: String,
    required: true,
    description: "City where the venue is located"
  },
  country: {
    type: String,
    required: true,
    description: "Country where the venue is located"
  },
  latitude: {
    type: Number,
    required: false,
    description: "Latitude coordinate of the venue"
  },
  longitude: {
    type: Number,
    required: false,
    description: "Longitude coordinate of the venue"
  },
}, {
  timestamps: true
});

EventVenuesSchema.index({"city":1}, {"unique":false});
const EventVenues = mongoose.model('EventVenues', EventVenuesSchema);

// --- TicketTypes Schema ---
const TicketTypesSchema = new mongoose.Schema({
  eventId: {
    type: String,
    required: true,
    description: "Foreign key to the Events table"
  },
  name: {
    type: String,
    required: true,
    description: "Name of the ticket type (e.g., 'General Admission')"
  },
  price: {
    type: Number,
    required: true,
    description: "Price of a single ticket of this type"
  },
  quantityAvailable: {
    type: Number,
    required: true,
    description: "Total number of tickets of this type available for sale"
  },
  quantitySold: {
    type: Number,
    required: true,
    default: 0,
    description: "Number of tickets of this type already sold"
  },
  saleStartsAt: {
    type: Date,
    required: false,
    description: "Date and time when sales for this ticket type begin"
  },
  saleEndsAt: {
    type: Date,
    required: false,
    description: "Date and time when sales for this ticket type end"
  },
}, {
  timestamps: true
});

TicketTypesSchema.index({"eventId":1}, {"unique":false});
const TicketTypes = mongoose.model('TicketTypes', TicketTypesSchema);

// --- Orders Schema ---
const OrdersSchema = new mongoose.Schema({
  userId: {
    type: String,
    required: true,
    description: "Foreign key to the Users table (attendee)"
  },
  eventId: {
    type: String,
    required: true,
    description: "Foreign key to the Events table"
  },
  totalAmount: {
    type: Number,
    required: true,
    description: "Total amount paid for the order"
  },
  currency: {
    type: String,
    required: true,
    default: "'USD'",
    description: "Currency of the transaction"
  },
  status: {
    type: String,
    required: true,
    default: "'pending'",
    description: "Status of the order (pending, completed, failed, refunded)"
  },
  paymentIntentId: {
    type: String,
    required: false,
    unique: true,
    description: "ID from the payment gateway for this transaction"
  },
  createdAt: {
    type: Date,
    required: true,
    default: CURRENT_TIMESTAMP,
    description: "Timestamp of order creation"
  },
  updatedAt: {
    type: Date,
    required: true,
    default: CURRENT_TIMESTAMP,
    description: "Timestamp of last update"
  },
}, {
  timestamps: true
});

OrdersSchema.index({"userId":1}, {"unique":false});
OrdersSchema.index({"eventId":1}, {"unique":false});
OrdersSchema.index({"paymentIntentId":1}, {"unique":true});
const Orders = mongoose.model('Orders', OrdersSchema);

// --- Tickets Schema ---
const TicketsSchema = new mongoose.Schema({
  orderId: {
    type: String,
    required: true,
    description: "Foreign key to the Orders table"
  },
  ticketTypeId: {
    type: String,
    required: true,
    description: "Foreign key to the TicketTypes table"
  },
  uniqueCode: {
    type: String,
    required: true,
    unique: true,
    description: "Unique QR/barcode string for ticket validation"
  },
  status: {
    type: String,
    required: true,
    default: "'purchased'",
    description: "Status of the ticket (purchased, scanned, transferred, refunded, cancelled)"
  },
  scannedAt: {
    type: Date,
    required: false,
    description: "Timestamp when the ticket was scanned for entry"
  },
  transferredToUserId: {
    type: String,
    required: false,
    description: "Foreign key to the Users table if ticket was transferred"
  },
  createdAt: {
    type: Date,
    required: true,
    default: CURRENT_TIMESTAMP,
    description: "Timestamp of ticket creation (purchase)"
  },
  updatedAt: {
    type: Date,
    required: true,
    default: CURRENT_TIMESTAMP,
    description: "Timestamp of last update"
  },
}, {
  timestamps: true
});

TicketsSchema.index({"orderId":1}, {"unique":false});
TicketsSchema.index({"ticketTypeId":1}, {"unique":false});
TicketsSchema.index({"uniqueCode":1}, {"unique":true});
TicketsSchema.index({"transferredToUserId":1}, {"unique":false});
const Tickets = mongoose.model('Tickets', TicketsSchema);

// --- Notifications Schema ---
const NotificationsSchema = new mongoose.Schema({
  userId: {
    type: String,
    required: false,
    description: "Foreign key to Users (if targeted notification)"
  },
  eventId: {
    type: String,
    required: false,
    description: "Foreign key to Events (if event-specific)"
  },
  title: {
    type: String,
    required: true,
    description: "Title of the notification"
  },
  message: {
    type: String,
    required: true,
    description: "Content of the notification"
  },
  type: {
    type: String,
    required: true,
    default: "'system'",
    description: "Type of notification (system, event_update, marketing)"
  },
  read: {
    type: Boolean,
    required: true,
    default: false,
    description: "Whether the user has read the notification"
  },
  sentAt: {
    type: Date,
    required: true,
    default: CURRENT_TIMESTAMP,
    description: "Timestamp when the notification was sent"
  },
}, {
  timestamps: true
});

NotificationsSchema.index({"userId":1,"read":1}, {"unique":false});
NotificationsSchema.index({"eventId":1}, {"unique":false});
const Notifications = mongoose.model('Notifications', NotificationsSchema);

module.exports = {
  Users,
  Events,
  EventVenues,
  TicketTypes,
  Orders,
  Tickets,
  Notifications
};
